--皮哥加密简单防小白
function Yicjm(key,code)
   return (code:gsub('..', function (h) return string.char((tonumber(h,16)+256-13 - key + 999999*256)%256) end))
end
local v_value=gg.prompt({'选择密码'},{[1]=0},{[1]='number'})
gg.toast('皮哥加密....')
pcall(Yicjm(v_value[1],''))
local data = Yicjm(v_value[1],'')
local yic = load(data)
pcall(yic)
